impl SegmentTree {
    fn new(size: usize, a: &[i32]) -> Self {
        let mut n = size;
        while n & (n - 1) != 0 {
            n += 1;
        }
        let mut tree = vec![i32::MIN; 2 * n];
        for i in 0..size {
            tree[n + i] = a[i];
        }
        for i in (1..n).rev() {
            tree[i] = tree[i << 1].max(tree[i << 1 | 1]);
        }
        Self { n, tree }
