   heap.Init(maxHeap)

   output := []int{}
   for i := 0; i < len(nums); i++ {
       heap.Push(maxHeap, [2]int{nums[i], i})
       if i >= k - 1 {
           for (*maxHeap)[0][1] <= i - k {
               heap.Pop(maxHeap)
           }
           output = append(output, (*maxHeap)[0][0])
